create or replace function dm_private.queue_submitted_drawing_reviews()returns trigger language plpgsql security definer set search_path=pg_catalog,dm_private as $$begin if old.status='active'and new.status='submitted'then insert into dm_private.drawing_reviews(attempt_id,question_id)select new.id,i.question_id from dm_private.attempt_items i where i.attempt_id=new.id and i.kind='drawing'and exists(select 1 from dm_private.drawing_uploads u where u.attempt_id=i.attempt_id and u.question_id=i.question_id)on conflict(attempt_id,question_id)do nothing;end if;return new;end$$;
create trigger queue_submitted_drawing_reviews after update of status on dm_private.attempts for each row execute function dm_private.queue_submitted_drawing_reviews();
insert into dm_private.drawing_reviews(attempt_id,question_id)select distinct i.attempt_id,i.question_id from dm_private.attempt_items i join dm_private.attempts a on a.id=i.attempt_id where a.status='submitted'and i.kind='drawing'and exists(select 1 from dm_private.drawing_uploads u where u.attempt_id=i.attempt_id and u.question_id=i.question_id)on conflict(attempt_id,question_id)do nothing;
create or replace function public.register_drawing_upload(p_attempt_id uuid,p_question_id uuid,p_storage_path text,p_ordinal integer,p_mime_type text,p_byte_size integer)returns uuid language plpgsql security definer set search_path=pg_catalog,dm_private as $$declare a dm_private.attempts;v uuid;begin if auth.role()is distinct from'service_role'then raise exception'Forbidden';end if;select*into a from dm_private.attempts where id=p_attempt_id for update;if a.id is null or coalesce(a.upload_deadline,a.deadline)<now()then raise exception'Upload window closed';end if;if not exists(select 1 from dm_private.attempt_items where attempt_id=a.id and question_id=p_question_id and kind='drawing')then raise exception'Drawing question not found';end if;insert into dm_private.drawing_uploads(attempt_id,question_id,student_id,storage_path,ordinal,mime_type,byte_size)values(a.id,p_question_id,a.user_id,p_storage_path,p_ordinal,p_mime_type,p_byte_size)returning id into v;if a.status='submitted'then insert into dm_private.drawing_reviews(attempt_id,question_id)values(a.id,p_question_id)on conflict(attempt_id,question_id)do nothing;end if;return v;end$$;
create or replace function public.admin_drawing_queue()returns jsonb language plpgsql stable security definer set search_path=pg_catalog,public,dm_private as $$begin if not public.is_dmocks_admin()then raise exception'Admin access required';end if;return(select coalesce(jsonb_agg(jsonb_build_object('reviewId',r.id,'attemptId',r.attempt_id,'questionId',r.question_id,'prompt',i.prompt,'status',r.status,'uploadCount',(select count(*)from dm_private.drawing_uploads u where u.attempt_id=r.attempt_id and u.question_id=r.question_id),'maxScore',i.points,'criteria',r.criterion_marks,'comments',r.comments,'score',r.score,'reviewedAt',r.reviewed_at,'releasedAt',r.released_at)order by case r.status when'pending'then 1 when'assigned'then 2 when'reviewed'then 3 else 4 end,r.id),'[]')from dm_private.drawing_reviews r join dm_private.attempt_items i on i.attempt_id=r.attempt_id and i.question_id=r.question_id);end$$;
create or replace function public.admin_review_drawing(p_review_id uuid,p_criterion_marks jsonb,p_comments text,p_score numeric,p_override_reason text default null)returns void language plpgsql security definer set search_path=pg_catalog,public,dm_private as $$declare r dm_private.drawing_reviews;v_max numeric;v_action text;begin if not public.is_dmocks_admin()then raise exception'Admin access required';end if;select*into r from dm_private.drawing_reviews where id=p_review_id for update;if r.id is null then raise exception'Review not found';end if;select points into v_max from dm_private.attempt_items where attempt_id=r.attempt_id and question_id=r.question_id;if jsonb_typeof(p_criterion_marks)<>'object'or p_criterion_marks='{}'::jsonb or exists(select 1 from jsonb_each(p_criterion_marks)e where jsonb_typeof(e.value)<>'number'or(e.value#>>'{}')::numeric<0)or p_score<0 or p_score>v_max or char_length(trim(p_comments))<5 then raise exception'Invalid review';end if;v_action:=case when r.status in('reviewed','released')then'override'else'review'end;if v_action='override'and nullif(trim(p_override_reason),'')is null then raise exception'Override reason required';end if;update dm_private.drawing_reviews set reviewer_id=auth.uid(),status='reviewed',criterion_marks=p_criterion_marks,comments=trim(p_comments),score=p_score,override_reason=nullif(trim(p_override_reason),''),reviewed_at=now(),released_at=null where id=r.id;insert into dm_private.drawing_review_audit(review_id,actor_id,action,payload)values(r.id,auth.uid(),v_action,jsonb_build_object('criteria',p_criterion_marks,'score',p_score,'overrideReason',p_override_reason));end$$;
create or replace function public.admin_release_drawing_review(p_review_id uuid)returns void language plpgsql security definer set search_path=pg_catalog,public,dm_private as $$begin if not public.is_dmocks_admin()then raise exception'Admin access required';end if;update dm_private.drawing_reviews set status='released',released_at=now()where id=p_review_id and status='reviewed'and score is not null and comments is not null;if not found then raise exception'Review is not ready for release';end if;insert into dm_private.drawing_review_audit(review_id,actor_id,action)values(p_review_id,auth.uid(),'release');end$$;
create or replace function public.read_attempt(p_id uuid)returns jsonb language plpgsql security definer set search_path=pg_catalog,dm_private as $$declare a dm_private.attempts;items jsonb;v_pending boolean;v_review_ends_at timestamptz;begin select*into a from dm_private.attempts where id=p_id and user_id=auth.uid();if a.id is null then raise exception'Attempt not found';end if;select e.results_released_at is null,e.review_ends_at into v_pending,v_review_ends_at from dm_private.all_india_attempts ai join dm_private.all_india_events e on e.id=ai.event_id where ai.attempt_id=a.id;v_pending:=coalesce(v_pending,false)and a.status='submitted';select coalesce(jsonb_agg(jsonb_build_object('id',i.question_id,'ordinal',i.ordinal,'prompt',i.prompt,'options',i.options,'topic',i.topic,'answer',i.answer,'points',i.points,'negativePoints',i.negative_points,'marking',i.marking,'kind',i.kind,'media',i.media)||case when a.status='submitted'and not v_pending then jsonb_build_object('correctKey',i.key,'explanation',i.explanation,'outcome',(select outcome from dm_private.score_response(i.kind,i.key,i.answer,i.marking)))else'{}'::jsonb end||case when a.status='submitted'and i.kind='drawing'then jsonb_build_object('drawingReview',coalesce((select case when r.status='released'then jsonb_build_object('status','released','criteria',r.criterion_marks,'comments',r.comments,'score',r.score,'maxScore',i.points,'releasedAt',r.released_at)else jsonb_build_object('status','pending')end from dm_private.drawing_reviews r where r.attempt_id=i.attempt_id and r.question_id=i.question_id),jsonb_build_object('status','not_submitted')))else'{}'::jsonb end order by i.ordinal),'[]')into items from dm_private.attempt_items i where i.attempt_id=a.id;return jsonb_build_object('title',(select title from dm_private.papers where id=a.paper_id),'id',a.id,'status',a.status,'deadline',a.deadline,'serverNow',now(),'score',case when v_pending then null else a.score end,'total',case when v_pending then null else a.total end,'resultsPending',v_pending,'reviewEndsAt',v_review_ends_at,'questions',case when v_pending then'[]'::jsonb else items end);end$$;
revoke all on function public.admin_release_drawing_review(uuid)from public,anon;
grant execute on function public.admin_release_drawing_review(uuid)to authenticated;
